(() => {
  'use strict';
  const F=window.NicoChar,A=window.NicoCharArt,$=id=>document.getElementById(id),clone=x=>structuredClone(x),escape=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const label=id=>id.replaceAll('-',' ').toUpperCase();
  const categories=[['archetype','01 / TEMAS'],['style','ESTILO'],['body','CORPO'],['hair','CABEÇA / CABELO'],['eyes','OLHOS'],['face','ROSTO'],['clothing','ROUPAS'],['accessory','ACESSÓRIOS'],['pose','POSE'],['palette','PALETA'],['scene','CENÁRIO'],['companion','COMPANION'],['frame','MOLDURA'],['emote','EMOTE'],['effect','EFEITOS'],['mode','EXIBIÇÃO'],['drawing','DESENHO LIVRE'],['studio','MINI ESTÚDIO'],['identity','IDENTIDADE'],['rewards','CONQUISTAS']];
  const badges={'primeiro-preset':'Primeiro preset público','criador-aprovado':'Criação aprovada',favoriteiro:'10 presets favoritos','sete-dias':'7 dias seguidos','perfil-criado':'Personagem criado',explorador:'Ferramenta explorada',halloween:'Halloween',natal:'Natal retrô',aniversario:'Aniversário NICHODEVS',desafio:'Desafio da comunidade'};
  let commentsVersion=0,userEpoch=0,request,user,own,editor,dirty=false,undo=[],redo=[],category='archetype',draft,revision=0,animator=null,frame=0,onSaved=async()=>{},tool='pencil',ink=2,mirror=false,cursor={x:0,y:0},stroke=null;
  const message=(value,error=false)=>{const e=$('nicoStatus');if(e){e.textContent=value;e.classList.toggle('nico-danger',error);}};
  const snapshot=()=>{undo.push(clone(draft));if(undo.length>50)undo.shift();redo=[];dirty=true;};
  function canvas(design,size=128,scene=true){const c=document.createElement('canvas');c.width=size;c.height=size;c.setAttribute('role','img');c.setAttribute('aria-label','Personagem '+design.name);A.paint(c,design,0,{scene});return c;}
  function identity(username,record){const a=document.createElement('a');a.href='#perfil/'+encodeURIComponent(username);a.className='nico-identity';a.append(canvas(record?.design||F.defaults,40,false));const s=document.createElement('span');s.textContent='@'+username;a.append(s);return a;}
  function card(design,username='',level){const c=document.createElement('div');c.className='nico-card';c.dataset.mode=design.mode;c.append(canvas(design));const info=document.createElement('div'),name=document.createElement('strong');name.textContent=design.name;info.append(name);const sub=document.createElement('small');sub.textContent=(username?'@'+username+' · ':'')+label(design.archetype)+(level?' · LV '+level:'');info.append(sub);if(design.badges?.length){const p=document.createElement('small');p.textContent=design.badges.map(x=>badges[x]||x).join(' · ');info.append(p);}c.append(info);const sprite=c.querySelector('canvas');let tick=null,step=0;const pause=()=>{clearInterval(tick);tick=null;step=0;A.paint(sprite,design);};const play=()=>{pause();if(!design.animation||matchMedia('(prefers-reduced-motion: reduce)').matches)return;tick=setInterval(()=>{if(!c.isConnected||document.hidden){pause();return;}A.paint(sprite,design,(++step)%4);},350);};sprite.tabIndex=0;sprite.setAttribute('aria-label','Personagem '+design.name+'. Foco ou mouse anima; sair pausa.');sprite.onpointerenter=sprite.onfocus=play;sprite.onpointerleave=sprite.onblur=pause;return c;}
  async function setUser(call,next,saved){request=call;onSaved=saved||onSaved;const epoch=++userEpoch,changed=user?.id!==next?.id;user=next;if(changed){stop();editor?.replaceChildren();$('nicoStudio')?.replaceChildren();$('nicoComments')?.replaceChildren();commentsVersion++;dirty=false;draft=null;editor=null;own=null;undo=[];redo=[];header();}const loaded=next?await call('/char'):null;if(epoch===userEpoch)own=loaded;}
  function header(){const c=$('headerCharCanvas');const d=own?.design||F.defaults;A.paint(c,d,0,{scene:false});c.setAttribute('aria-label',user?'Seu CHAR: '+d.name:'CHAR padrão');$('headerChar').title=user?'Personalizar '+d.name:'Criar meu CHAR';}
  function studio(root){root.replaceChildren();root.hidden=!user;if(!user)return;root.className='nico-surface nico-profile';const d=own?.design||F.defaults;root.append(card(d,user.username,own?.level));const info=document.createElement('div');info.className='nico-profile-text';info.innerHTML='<p class="nico-code">ID CARD / NICO//CHAR</p><h2>MEU PERSONAGEM</h2><p></p><div class="nico-profile-actions"><a class="button outline compact" href="#char">PERSONALIZAR →</a><a class="text-link" href="#perfil/'+encodeURIComponent(user.username)+'">VER MEU PERFIL</a></div>';info.querySelector('h2+p').textContent=d.mood;const note=document.createElement('p');note.className='nico-note';note.textContent=d.hidden?'Char público oculto.':own?.status==='pending'?'Desenho em revisão; o público continua vendo sua última versão aprovada.':own?.status==='hidden'?'Desenho oculto pela moderação: '+own.reason:'Seu char acompanha suas criações e presets.';info.append(note);root.append(info);}
  function stop(){clearInterval(animator);animator=null;frame=0;if(editor&&draft&&$('nicoPreview'))A.paint($('nicoPreview'),draft);}
  function animate(){stop();if(!draft?.animation||matchMedia('(prefers-reduced-motion: reduce)').matches||document.hidden)return;animator=setInterval(()=>{if(document.hidden){stop();return;}if($('nicoPreview'))A.paint($('nicoPreview'),draft,(++frame)%4);},300);}
  function preview(){if(!$('nicoPreview'))return;A.paint($('nicoPreview'),draft);$('nicoName').textContent=draft.name;$('nicoClass').textContent=label(draft.archetype)+' / '+label(draft.style);$('nicoUndo').disabled=!undo.length;$('nicoRedo').disabled=!redo.length;$('nicoAnimate').textContent=draft.animation?'PAUSAR ANIMAÇÃO':'ANIMAR';}
  function apply(key,id){snapshot();if(key==='archetype'){const keep={name:draft.name,mood:draft.mood,hidden:draft.hidden};draft={...F.make(id),...keep};}else{draft[key]=id;if(key==='style'){if(id==='underground-hacker'){draft.hair='capuz';draft.clothing='sobretudo';}if(id==='cyber-mascot'){draft.hair='crt';draft.body='robo';}if(id==='pocket-rpg'){draft.hair='curto';draft.body='medio';}}}stop();preview();library();message('Mudanças ainda não salvas.');}
  function field(id,title,value,type='text',extra=''){return '<label for="'+id+'">'+title+'</label><input id="'+id+'" type="'+type+'" value="'+escape(value)+'" '+extra+'>';}
  function library(){
    const root=$('nicoLibrary');if(!root)return;root.replaceChildren();const h=document.createElement('h3');h.textContent=categories.find(x=>x[0]===category)[1];root.append(h);
    if(F.catalog[category]){
      const grid=document.createElement('div');grid.className='nico-options';
      for(const item of F.catalog[category]){const b=document.createElement('button');b.type='button';b.className='nico-option';b.setAttribute('aria-label',label(item.id));b.setAttribute('aria-pressed',String(draft[category]===item.id));const locked=F.required(category,item.id);b.disabled=Boolean(locked&&!own?.unlocks.includes(locked));const design=category==='archetype'?F.make(item.id):{...draft,[category]:item.id};b.append(canvas(design,64));const s=document.createElement('span');s.textContent=label(item.id);b.append(s);if(b.disabled){const note=document.createElement('small');note.textContent='🔒 '+(badges[locked]||locked);b.append(note);}b.onclick=()=>apply(category,item.id);grid.append(b);}root.append(grid);
      if(category==='companion'){const l=document.createElement('label');l.textContent='POSIÇÃO';const s=document.createElement('select');s.setAttribute('aria-label','Posição do companion');for(const x of F.catalog.companionPosition){const o=document.createElement('option');o.value=x.id;o.textContent=label(x.id);s.append(o);}s.value=draft.companionPosition;s.onchange=()=>{snapshot();draft.companionPosition=s.value;preview();};l.append(s);root.append(l);}
      return;
    }
    if(category==='identity'){
      root.innerHTML+='<p>O nome é público. Nunca inclua senhas ou contato pessoal.</p>'+field('nicoCharName','NOME DO CHAR',draft.name,'text','maxlength="24"')+field('nicoMood','MOOD',draft.mood,'text','maxlength="80"')+'<label class="nico-label-inline"><input id="nicoHidden" type="checkbox"> Ocultar char público</label>';
      $('nicoHidden').checked=draft.hidden;for(const [id,key]of [['nicoCharName','name'],['nicoMood','mood'],['nicoHidden','hidden']])$(id).oninput=()=>{snapshot();draft[key]=$(id).type==='checkbox'?$(id).checked:$(id).value;preview();};return;
    }
    if(category==='studio'){
      root.innerHTML+='<p>Seu quarto 8-bit. Escolha os objetos e a posição do companion.</p><button type="button" id="nicoRoom">USAR CENÁRIO QUARTO</button><div class="nico-studio-controls"></div>';
      $('nicoRoom').onclick=()=>apply('scene','quarto');const controls=root.querySelector('.nico-studio-controls');for(const [k,l]of [['desk','Mesa'],['pc','Computador'],['guitar','Guitarra'],['speakers','Caixas de som'],['poster','Poster'],['lights','Luzes']]){const lab=document.createElement('label');lab.className='nico-label-inline';const input=document.createElement('input');input.type='checkbox';input.checked=draft.studio[k];input.onchange=()=>{snapshot();draft.studio[k]=input.checked;preview();};lab.append(input,document.createTextNode(l));controls.append(lab);}
      for(const [key,l]of [['petX','Companion horizontal'],['petY','Companion vertical']]){const lab=document.createElement('label');lab.textContent=l;const input=document.createElement('input');input.type='range';input.min=2;input.max=52;input.value=draft.studio[key];input.onchange=()=>{snapshot();draft.studio[key]=Number(input.value);preview();};lab.append(input);root.append(lab);}return;
    }
    if(category==='rewards'){
      const grid=document.createElement('div');grid.className='nico-rewards';for(const [id,l]of Object.entries(badges)){const row=document.createElement('div'),earned=own?.unlocks.includes(id);row.textContent=(earned?'✓ ':'○ ')+l;if(earned){const input=document.createElement('input');input.type='checkbox';input.checked=draft.badges.includes(id);input.setAttribute('aria-label','Equipar '+l);input.onchange=()=>{if(input.checked&&draft.badges.length>=3){input.checked=false;message('Equipe no máximo três badges.',true);return;}snapshot();draft.badges=input.checked?[...draft.badges,id]:draft.badges.filter(x=>x!==id);preview();};row.prepend(input);}grid.append(row);}root.append(grid);const note=document.createElement('p');note.className='nico-note';note.textContent='Sem competição. Até 3 badges equipadas. Eventos e desafios são concedidos pela equipe; não aumentam permissões nem destaque.';root.append(note);return;
    }
    if(category==='drawing')drawingLibrary(root);
  }
  function drawingLibrary(root){
    root.innerHTML+='<p>Arte livre em pixels. O desenho substitui o corpo modular e passa por revisão antes de aparecer publicamente.</p><div class="nico-draw-tools"><button type="button" data-draw-size="16">16×16</button><button type="button" data-draw-size="32">32×32</button><button type="button" id="nicoModular">VOLTAR ÀS PEÇAS</button></div><div class="nico-draw-tools" role="group" aria-label="Ferramentas de desenho"><button type="button" data-draw-tool="pencil">LÁPIS</button><button type="button" data-draw-tool="eraser">BORRACHA</button><button type="button" data-draw-tool="fill">PREENCHER</button></div><div id="nicoSwatches" class="nico-swatches" role="group" aria-label="Cores do desenho"></div><label class="nico-label-inline"><input id="nicoMirror" type="checkbox"> Espelhamento horizontal</label><canvas id="nicoDrawing" class="nico-drawing" width="256" height="256" tabindex="0" role="img" aria-label="Grade de desenho. Setas movem o cursor; espaço ou Enter pinta; Z desfaz."></canvas><p id="nicoCursor" class="nico-note" aria-live="polite"></p><p class="nico-note">Setas: mover · Espaço: pintar · Z: desfazer. Transparência é a primeira cor. A grade não aparece na exportação.</p>';
    root.querySelectorAll('[data-draw-size]').forEach(b=>{b.setAttribute('aria-pressed',String(draft.drawing?.size===Number(b.dataset.drawSize)));b.onclick=()=>{snapshot();const size=Number(b.dataset.drawSize),old=draft.drawing;draft.drawing={size,pixels:Array.from({length:size*size},(_,i)=>old?old.pixels[Math.floor(Math.floor(i/size)*old.size/size)*old.size+Math.floor((i%size)*old.size/size)]:'0').join('')};cursor={x:0,y:0};preview();library();};});
    $('nicoModular').onclick=()=>{snapshot();draft.drawing=null;preview();library();};
    root.querySelectorAll('[data-draw-tool]').forEach(b=>{b.setAttribute('aria-pressed',String(tool===b.dataset.drawTool));b.onclick=()=>{tool=b.dataset.drawTool;library();};});
    const colors=['transparent',...F.colors[draft.palette]];colors.forEach((color,i)=>{const b=document.createElement('button');b.type='button';b.className='nico-swatch';b.style.setProperty('--swatch',color);b.setAttribute('aria-label',i?'Cor '+i:'Transparente');b.setAttribute('aria-pressed',String(ink===i));b.onclick=()=>{ink=i;library();};$('nicoSwatches').append(b);});
    $('nicoMirror').checked=mirror;$('nicoMirror').onchange=e=>mirror=e.target.checked;
    const canvas=$('nicoDrawing');const position=e=>{const r=canvas.getBoundingClientRect(),size=draft.drawing?.size||32;return {x:Math.max(0,Math.min(size-1,Math.floor((e.clientX-r.left)*size/r.width))),y:Math.max(0,Math.min(size-1,Math.floor((e.clientY-r.top)*size/r.height)))};};
    canvas.onpointerdown=e=>{e.preventDefault();canvas.focus();canvas.setPointerCapture(e.pointerId);snapshot();if(!draft.drawing)draft.drawing={size:32,pixels:'0'.repeat(1024)};cursor=position(e);stroke=cursor;drawAt(cursor.x,cursor.y);};
    canvas.onpointermove=e=>{if(!stroke)return;const p=position(e);if(tool!=='fill'){let {x,y}=stroke;const dx=Math.abs(p.x-x),sx=x<p.x?1:-1,dy=-Math.abs(p.y-y),sy=y<p.y?1:-1;let error=dx+dy;for(let n=0;n<64;n++){drawAt(x,y,false);if(x===p.x&&y===p.y)break;const twice=2*error;if(twice>=dy){error+=dy;x+=sx;}if(twice<=dx){error+=dx;y+=sy;}}cursor=p;stroke=p;drawGrid();preview();}};
    canvas.onpointerup=canvas.onpointercancel=()=>{stroke=null;};
    canvas.onkeydown=e=>{const size=draft.drawing?.size||32;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' ','Enter','z','Z'].includes(e.key))e.preventDefault();if(e.key==='ArrowUp')cursor.y=Math.max(0,cursor.y-1);if(e.key==='ArrowDown')cursor.y=Math.min(size-1,cursor.y+1);if(e.key==='ArrowLeft')cursor.x=Math.max(0,cursor.x-1);if(e.key==='ArrowRight')cursor.x=Math.min(size-1,cursor.x+1);if(e.key===' '||e.key==='Enter'){snapshot();if(!draft.drawing)draft.drawing={size:32,pixels:'0'.repeat(1024)};drawAt(cursor.x,cursor.y);}if(e.key.toLowerCase()==='z')undoEdit(false);drawGrid();};drawGrid();
  }
  function drawAt(x,y,repaint=true){const d=draft.drawing;if(!d)return;const p=d.pixels.split(''),color=String(tool==='eraser'?0:ink),size=d.size;const set=(xx,yy)=>{if(tool!=='fill'){p[yy*size+xx]=color;return;}const old=p[yy*size+xx];if(old===color)return;const stack=[yy*size+xx];while(stack.length){const i=stack.pop();if(p[i]!==old)continue;p[i]=color;const px=i%size,py=Math.floor(i/size);if(px>0)stack.push(i-1);if(px<size-1)stack.push(i+1);if(py>0)stack.push(i-size);if(py<size-1)stack.push(i+size);}};set(x,y);if(mirror)set(size-1-x,y);d.pixels=p.join('');if(repaint){drawGrid();preview();}message('Desenho ainda não salvo.');}
  function drawGrid(){const canvas=$('nicoDrawing');if(!canvas)return;const ctx=canvas.getContext('2d'),d=draft.drawing||{size:32,pixels:'0'.repeat(1024)},scale=256/d.size;ctx.clearRect(0,0,256,256);const colors=['transparent',...F.colors[draft.palette]];for(let i=0;i<d.pixels.length;i++){if(d.pixels[i]==='0')continue;ctx.fillStyle=colors[Number(d.pixels[i])];ctx.fillRect(i%d.size*scale,Math.floor(i/d.size)*scale,scale,scale);}ctx.strokeStyle='#ffffff20';ctx.lineWidth=1;for(let i=0;i<=d.size;i++){ctx.beginPath();ctx.moveTo(i*scale+.5,0);ctx.lineTo(i*scale+.5,256);ctx.stroke();ctx.beginPath();ctx.moveTo(0,i*scale+.5);ctx.lineTo(256,i*scale+.5);ctx.stroke();}ctx.strokeStyle='#f7c75f';ctx.strokeRect(cursor.x*scale+.5,cursor.y*scale+.5,scale-1,scale-1);$('nicoCursor').textContent='Pixel '+(cursor.x+1)+', '+(cursor.y+1)+' · '+d.size+'×'+d.size;}
  function undoEdit(forward){const from=forward?redo:undo,to=forward?undo:redo;if(!from.length)return;to.push(clone(draft));draft=from.pop();dirty=true;stop();preview();library();}
  function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function exportPNG(scene=false){const c=canvas(draft,256,scene);c.toBlob(blob=>{if(blob)download(blob,'nico-char'+(scene?'-card':'')+'.png');else message('Não foi possível exportar.',true);},'image/png');}
  async function mount(root){
    stop();editor=root;draft=clone(own?.design||F.defaults);revision=own?.revision||0;dirty=false;undo=[];redo=[];category='archetype';root.className='nico-surface';
    root.innerHTML='<div class="nico-head"><div><small>NICHODEVS / CHARACTER SYSTEM</small><div class="nico-title">NICO//CHAR</div></div><div class="nico-code">CHAR LAB<br>SEU PIXEL. SUA IDENTIDADE.</div></div><div class="nico-workbench"><nav id="nicoCategories" class="nico-categories" aria-label="Camadas do personagem"></nav><div class="nico-stage"><p class="nico-code">PREVIEW / PIXEL PERFECT</p><canvas id="nicoPreview" class="nico-preview" width="256" height="256" role="img" tabindex="0" aria-label="Prévia do personagem; anima ao passar o mouse"></canvas><div class="nico-id"><strong id="nicoName"></strong><small id="nicoClass"></small></div><div class="nico-tools"><button type="button" id="nicoAnimate">ANIMAR</button><button type="button" id="nicoUndo">↶ DESFAZER</button><button type="button" id="nicoRedo">↷ REFAZER</button></div><p class="nico-note">Passe o mouse para animar.<br>Movimento reduzido é respeitado.</p><div class="nico-export"><button type="button" id="nicoPNG">PNG TRANSPARENTE ↓</button><button type="button" id="nicoGIF">GIF ANIMADO ↓</button><button type="button" id="nicoCardPNG">PNG DO CARD ↓</button></div></div><aside id="nicoLibrary" class="nico-library" aria-label="Biblioteca de peças"></aside></div><div class="nico-bottom"><div><p id="nicoStatus" class="nico-status" role="status" aria-live="polite"></p><small class="nico-code">'+(user?'SALVA NA SUA CONTA / SEM IA':'PRÉVIA LIVRE / ENTRE PARA SALVAR')+'</small></div><div class="nico-tools"><button type="button" id="nicoReset">RESTAURAR PADRÃO</button><button type="button" id="nicoDiscard">DESCARTAR</button><button type="button" id="nicoSave" class="nico-save">SALVAR CHAR →</button></div></div>';
    for(const [id,l]of categories){const b=document.createElement('button');b.type='button';b.textContent=l;b.dataset.category=id;b.setAttribute('aria-current',String(id===category));b.onclick=()=>{category=id;root.querySelectorAll('[data-category]').forEach(x=>x.setAttribute('aria-current',String(x===b)));library();};$('nicoCategories').append(b);}
    $('nicoPreview').onpointerenter=$('nicoPreview').onfocus=animate;$('nicoPreview').onpointerleave=$('nicoPreview').onblur=stop;
    $('nicoAnimate').onclick=()=>{snapshot();draft.animation=!draft.animation;preview();if(draft.animation)animate();else stop();};$('nicoUndo').onclick=()=>undoEdit(false);$('nicoRedo').onclick=()=>undoEdit(true);
    $('nicoPNG').onclick=()=>exportPNG();$('nicoCardPNG').onclick=()=>exportPNG(true);$('nicoGIF').onclick=()=>download(new Blob([A.gif(draft)],{type:'image/gif'}),'nico-char.gif');
    $('nicoReset').onclick=()=>{snapshot();draft=clone(F.defaults);stop();preview();library();message('Padrão restaurado na prévia. Salve para confirmar.');};
    $('nicoDiscard').onclick=()=>{draft=clone(own?.design||F.defaults);dirty=false;undo=[];redo=[];stop();preview();library();message('Mudanças descartadas.');};
    $('nicoSave').onclick=async()=>{if(!user){message('Entre na sua conta para salvar seu personagem.',true);return;}const button=$('nicoSave'),owner=user.id,screen=editor,sent=JSON.stringify(draft);button.disabled=true;try{F.validate(draft,own.unlocks);const saved=await request('/char',{method:'PUT',body:{design:draft,revision}});if(user?.id!==owner||editor!==screen)return;own=saved;revision=saved.revision;const newer=JSON.stringify(draft)!==sent;if(!newer){draft=clone(saved.design);dirty=false;undo=[];redo=[];}preview();library();await onSaved();message(newer?'Versão enviada salva. Há novas mudanças ainda não salvas.':saved.status==='pending'?'Salvo. Desenho livre enviado para revisão.':'Personagem salvo na sua conta.');}catch(error){message(error.message,true);}finally{button.disabled=false;}};
    preview();library();message(own?.status==='hidden'?'Oculto pela moderação: '+own.reason:'Escolha um tema ou monte peça por peça.');
  }
  function canLeave(){if(!dirty)return true;if(!confirm('Seu personagem tem mudanças não salvas. Descartar e sair do CHAR LAB?'))return false;dirty=false;stop();return true;}
  async function profile(root,username,page=1){stop();root.replaceChildren();const data=await request('/profiles/'+encodeURIComponent(username)+'?page='+page+'&size=12'),d=data.char?.design||F.defaults;const panel=document.createElement('div');panel.className='nico-surface nico-profile';panel.append(card(d,data.username,data.char?.level));const text=document.createElement('div');text.className='nico-profile-text';const h=document.createElement('h1');h.textContent='@'+data.username;const p=document.createElement('p');p.textContent=d.mood;text.append(h,p);const a=document.createElement('a');a.className='text-link';a.href='#char';a.textContent=user?.username===data.username?'PERSONALIZAR MEU CHAR':'CRIAR MEU CHAR';text.append(a);if(user&&user.username!==data.username&&data.char){const report=document.createElement('button');report.type='button';report.textContent='DENUNCIAR PERSONAGEM';report.className='text-link';report.onclick=async()=>{const reason=prompt('Motivo da denúncia (3–500 caracteres):');if(!reason)return;try{await request('/profiles/'+encodeURIComponent(username)+'/report',{method:'POST',body:{reason}});report.textContent='DENÚNCIA RECEBIDA';report.disabled=true;}catch(e){alert(e.message);}};text.append(report);}panel.append(text);root.append(panel);return data;}
  async function members(root,page=1,q=''){stop();const d=await request('/members?page='+page+'&size=24&q='+encodeURIComponent(q));root.replaceChildren();const form=document.createElement('form');form.innerHTML='<label for="nicoMemberSearch">BUSCAR USUÁRIO POR PREFIXO</label><div class="button-row"><input id="nicoMemberSearch" maxlength="24" pattern="[a-z0-9_]*" autocomplete="off"><button class="button outline compact" type="submit">BUSCAR</button></div>';form.querySelector('input').value=q;form.onsubmit=e=>{e.preventDefault();members(root,1,form.querySelector('input').value).catch(e=>{root.lastElementChild.textContent=e.message;});};root.append(form);const grid=document.createElement('div');grid.className='nico-member-grid';for(const item of d.items){const a=document.createElement('a');a.href='#perfil/'+encodeURIComponent(item.username);a.className='nico-surface';a.append(card(item.char.design,item.username,item.char.level));grid.append(a);}if(!d.items.length)grid.textContent='Nenhum personagem público nesta consulta.';root.append(grid);const controls=document.createElement('div');controls.className='nico-page-controls';for(const [direction,l]of [[-1,'← ANTERIOR'],[1,'PRÓXIMA →']]){const b=document.createElement('button');b.type='button';b.className='button outline compact';b.textContent=l;b.disabled=direction<0?page===1:page*d.size>=d.total;b.onclick=()=>members(root,page+direction,q).catch(e=>alert(e.message));controls.append(b);}const info=document.createElement('span');info.textContent='Página '+page+' · '+d.total+' personagens';controls.append(info);root.append(controls);}
  addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});addEventListener('pagehide',stop);document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});
  async function comments(root,item,page=1){
    const version=++commentsVersion;root.replaceChildren();if(item.visibility!=='public'||item.status!=='approved')return;
    const heading=document.createElement('h3');heading.textContent='COMENTÁRIOS';root.append(heading);
    const data=await request('/creations/'+encodeURIComponent(item.id)+'/comments?page='+page+'&size=25');if(version!==commentsVersion)return;
    for(const row of data.items){const article=document.createElement('article');article.className='nico-comment';article.append(identity(row.username,row.char));const body=document.createElement('p');body.textContent=row.body;body.style.whiteSpace='pre-wrap';article.append(body);const note=document.createElement('small');note.textContent=new Date(row.created).toLocaleDateString('pt-BR')+(row.status!=='approved'?' · '+(row.status==='pending'?'Em revisão, visível somente a você':'Oculto pela moderação'):'');article.append(note);if(row.mine){const b=document.createElement('button');b.type='button';b.className='text-link';b.textContent='EXCLUIR COMENTÁRIO';b.onclick=async()=>{if(!confirm('Excluir seu comentário?'))return;try{await request('/comments/'+row.id,{method:'DELETE',body:{revision:row.revision}});await comments(root,item,page);}catch(e){alert(e.message);}};article.append(b);}root.append(article);}
    if(data.total>25){const controls=document.createElement('div');controls.className='nico-page-controls';for(const [direction,l]of [[-1,'← ANTERIOR'],[1,'PRÓXIMA →']]){const b=document.createElement('button');b.type='button';b.textContent=l;b.className='text-link';b.disabled=direction<0?page===1:page*data.size>=data.total;b.onclick=()=>comments(root,item,page+direction).catch(e=>alert(e.message));controls.append(b);}root.append(controls);}
    const status=document.createElement('p');status.setAttribute('role','status');
    if(user){const form=document.createElement('form');form.innerHTML='<label for="nicoCommentBody">SEU COMENTÁRIO</label><textarea id="nicoCommentBody" rows="3" minlength="2" maxlength="600" required></textarea><p class="privacy-note">Comentários passam por revisão antes de aparecer publicamente.</p><button class="button outline compact" type="submit">ENVIAR PARA REVISÃO</button>';form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('button');b.disabled=true;try{await request('/creations/'+encodeURIComponent(item.id)+'/comments',{method:'POST',body:{body:form.querySelector('textarea').value}});await comments(root,item,page);root.lastElementChild.textContent='Comentário enviado para revisão.';}catch(e){status.textContent=e.message;b.disabled=false;}};root.append(form);}else status.textContent='Entre na sua conta para comentar.';
    root.append(status);
  }
  header();
  window.NicoCharUI={setUser,header,studio,mount,identity,card,canvas,profile,members,comments,canLeave,stop};
})();
